def RESULT_spec {α : Type u} (f : result α → α) : Prop := ∀ t, f (Result t) = t

def RESULT {α : Type u} : result α → α :=
  @Classical.epsilon _ ⟨fun r => match r with | .Result t => t | .Clash t => t⟩ RESULT_spec

theorem RESULT_def {α : Type u} : RESULT_spec (RESULT (α := α)) :=
  Classical.epsilon_spec (p := RESULT_spec (α := α)) ⟨fun r => match r with | .Result t => t | .Clash t => t, fun _ => rfl⟩

def CLASH_spec {α : Type u} (f : result α → α) : Prop := ∀ t, f (Clash t) = t

def CLASH {α : Type u} : result α → α :=
  @Classical.epsilon _ ⟨fun r => match r with | .Clash t => t | .Result t => t⟩ CLASH_spec

theorem CLASH_def {α : Type u} : CLASH_spec (CLASH (α := α)) :=
  Classical.epsilon_spec (p := CLASH_spec (α := α)) ⟨fun r => match r with | .Clash t => t | .Result t => t, fun _ => rfl⟩
